SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;
-- xxl_job DDL
CREATE DATABASE `xxl_job`
CHARACTER SET utf8mb4
COLLATE utf8mb4_unicode_ci;;
use `xxl_job`;
-- xxl_job.xxl_job_group DDL
CREATE TABLE `xxl_job`.`xxl_job_group` (`id` INT NOT NULL AUTO_INCREMENT,
`app_name` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment "执行器AppName",
`title` VARCHAR(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment "执行器名称",
`address_type` TINYINT NOT NULL DEFAULT 0 Comment "执行器地址类型：0=自动注册、1=手动录入",
`address_list` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器地址列表，多地址逗号分隔",
`update_time` DATETIME NULL,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 3 ROW_FORMAT = Dynamic;
-- xxl_job.xxl_job_info DDL
CREATE TABLE `xxl_job`.`xxl_job_info` (`id` INT NOT NULL AUTO_INCREMENT,
`job_group` INT NOT NULL Comment "执行器主键ID",
`job_desc` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
`add_time` DATETIME NULL,
`update_time` DATETIME NULL,
`author` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "作者",
`alarm_email` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "报警邮件",
`schedule_type` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' Comment "调度类型",
`schedule_conf` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "调度配置，值含义取决于调度类型",
`misfire_strategy` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'DO_NOTHING' Comment "调度过期策略",
`executor_route_strategy` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器路由策略",
`executor_handler` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器任务handler",
`executor_param` VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器任务参数",
`executor_block_strategy` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "阻塞处理策略",
`executor_timeout` INT NOT NULL DEFAULT 0 Comment "任务执行超时时间，单位秒",
`executor_fail_retry_count` INT NOT NULL DEFAULT 0 Comment "失败重试次数",
`glue_type` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment "GLUE类型",
`glue_source` MEDIUMTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "GLUE源代码",
`glue_remark` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "GLUE备注",
`glue_updatetime` DATETIME NULL Comment "GLUE更新时间",
`child_jobid` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "子任务ID，多个逗号分隔",
`trigger_status` TINYINT NOT NULL DEFAULT 0 Comment "调度状态：0-停止，1-运行",
`trigger_last_time` BIGINT NOT NULL DEFAULT 0 Comment "上次调度时间",
`trigger_next_time` BIGINT NOT NULL DEFAULT 0 Comment "下次调度时间",
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 4 ROW_FORMAT = Dynamic;
-- xxl_job.xxl_job_lock DDL
CREATE TABLE `xxl_job`.`xxl_job_lock` (`lock_name` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment "锁名称",
PRIMARY KEY (`lock_name`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;
-- xxl_job.xxl_job_log DDL
CREATE TABLE `xxl_job`.`xxl_job_log` (`id` BIGINT NOT NULL AUTO_INCREMENT,
`job_group` INT NOT NULL Comment "执行器主键ID",
`job_id` INT NOT NULL Comment "任务，主键ID",
`executor_address` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器地址，本次执行的地址",
`executor_handler` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器任务handler",
`executor_param` VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器任务参数",
`executor_sharding_param` VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行器任务分片参数，格式如 1/2",
`executor_fail_retry_count` INT NOT NULL DEFAULT 0 Comment "失败重试次数",
`trigger_time` DATETIME NULL Comment "调度-时间",
`trigger_code` INT NOT NULL Comment "调度-结果",
`trigger_msg` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "调度-日志",
`handle_time` DATETIME NULL Comment "执行-时间",
`handle_code` INT NOT NULL Comment "执行-状态",
`handle_msg` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "执行-日志",
`alarm_status` TINYINT NOT NULL DEFAULT 0 Comment "告警状态：0-默认、1-无需告警、2-告警成功、3-告警失败",
INDEX `I_handle_code`(`handle_code` ASC) USING BTREE,
INDEX `I_job_id`(`job_id` ASC) USING BTREE,
INDEX `I_jobid_jobgroup`(`job_id` ASC,`job_group` ASC) USING BTREE,
INDEX `I_trigger_time`(`trigger_time` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 1 ROW_FORMAT = Dynamic;
-- xxl_job.xxl_job_log_report DDL
CREATE TABLE `xxl_job`.`xxl_job_log_report` (`id` INT NOT NULL AUTO_INCREMENT,
`trigger_day` DATETIME NULL Comment "调度-时间",
`running_count` INT NOT NULL DEFAULT 0 Comment "运行中-日志数量",
`suc_count` INT NOT NULL DEFAULT 0 Comment "执行成功-日志数量",
`fail_count` INT NOT NULL DEFAULT 0 Comment "执行失败-日志数量",
`update_time` DATETIME NULL,
UNIQUE INDEX `i_trigger_day`(`trigger_day` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 5 ROW_FORMAT = Dynamic;
-- xxl_job.xxl_job_logglue DDL
CREATE TABLE `xxl_job`.`xxl_job_logglue` (`id` INT NOT NULL AUTO_INCREMENT,
`job_id` INT NOT NULL Comment "任务，主键ID",
`glue_type` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "GLUE类型",
`glue_source` MEDIUMTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "GLUE源代码",
`glue_remark` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment "GLUE备注",
`add_time` DATETIME NULL,
`update_time` DATETIME NULL,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;
-- xxl_job.xxl_job_registry DDL
CREATE TABLE `xxl_job`.`xxl_job_registry` (`id` INT NOT NULL AUTO_INCREMENT,
`registry_group` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
`registry_key` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
`registry_value` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
`update_time` DATETIME NULL,
UNIQUE INDEX `i_g_k_v`(`registry_group` ASC,`registry_key` ASC,`registry_value` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 1 ROW_FORMAT = Dynamic;
-- xxl_job.xxl_job_user DDL
CREATE TABLE `xxl_job`.`xxl_job_user` (`id` INT NOT NULL AUTO_INCREMENT,
`username` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment "账号",
`password` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment "密码加密信息",
`token` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "登录token",
`role` TINYINT NOT NULL Comment "角色：0-普通用户、1-管理员",
`permission` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment "权限：执行器ID列表，多个逗号分割",
UNIQUE INDEX `i_username`(`username` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 2 ROW_FORMAT = Dynamic;
